using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class PopulateNature {
 [MenuItem("Vampire Demo/Populate Nature Review")]
 public static void Run(){var s=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueVillageLayoutReview.unity");EditorSceneManager.SaveScene(s,"Assets/Demo/Scenes/PrologueNatureReview.unity",true);s=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueNatureReview.unity");var root=new GameObject("Nature additions review");string basep="Assets/Polyeler/EssentialNaturePack/Prefabs/";string[] names={"JapaneseLaurel","JapaneseEurya","Mugwort","Rock_A","Rock_B","Decayed_wood_A","FallenLeaves"};var rng=new System.Random(3200);for(int i=0;i<95;i++){float x=(float)(rng.NextDouble()*55-58),z=(float)(rng.NextDouble()*58-29);if(System.Math.Abs(z)<7|| (x>-40&&x<-25&&z>-12&&z<5))continue;var p=AssetDatabase.LoadAssetAtPath<GameObject>(basep+names[i%names.Length]+".prefab");if(!p)continue;var o=(GameObject)PrefabUtility.InstantiatePrefab(p);o.transform.SetParent(root.transform);o.transform.position=new Vector3(x,0,z);o.transform.rotation=Quaternion.Euler(0,rng.Next(360),0);}
 string[] trees={"PF Conifer Tall BOTD URP","PF Conifer Medium BOTD URP","PF Conifer Small BOTD URP"};for(int i=0;i<40;i++){float x=(float)(rng.NextDouble()*55+3),z=(float)(rng.NextDouble()*60-30);if(System.Math.Abs(z)<8)continue;var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Forst/Conifers [BOTD]/Render Pipeline Support/URP/Prefabs/"+trees[i%3]+".prefab");if(!p)continue;var o=(GameObject)PrefabUtility.InstantiatePrefab(p);o.transform.SetParent(root.transform);o.transform.position=new Vector3(x,0,z);o.transform.rotation=Quaternion.Euler(0,rng.Next(360),0);}
 EditorSceneManager.SaveScene(s);Debug.Log("NATURE_REVIEW_SAVED");}
}
